import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // For navigation
import './login-page.css'; // Custom CSS for styling
import Header from '../../components/Header/Header'; // Header component
import Footer from '../../components/Footer/Footer'; // Footer component

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState<string>(''); // State for email input
  const [password, setPassword] = useState<string>(''); // State for password input
  const [userType, setUserType] = useState<string>(''); // State for user type selection
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false); // State to manage form submission
  const navigate = useNavigate(); // Initialize the useNavigate hook

  // Handle the form submission
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault(); // Prevent default form submission
    if (isSubmitting) return; // Prevent multiple submissions

    // Basic validation for the email, password, and user type fields
    if (!email.trim() || !password.trim() || !userType.trim()) {
      alert('Please fill in all fields.');
      return;
    }

    setIsSubmitting(true);
    const payload = { email, password, userType };

    try {
      console.log("Sending payload:", JSON.stringify(payload, null, 2)); // Debugging

      const response = await fetch('http://localhost:5000/login_user', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const data = await response.json(); // Parse JSON response
      console.log("Response Data:", data);

      if (response.status === 200) {
        alert('Login successful!');

        // Store user email and roll number in local storage
        localStorage.setItem('userEmail', email);
        if (data.roll_number) {
          localStorage.setItem('rollNumber', data.roll_number);
        }

        // Redirect based on user type
        navigate(userType === 'admin' ? '/admin' : '/dashboard');
      } else {
        alert(data.error || 'Login failed. Please try again.');
      }
    } catch (error) {
      console.error('Login failed:', error);
      alert('An error occurred. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-page">
      <Header />
      <div className='login-content'>
        <div className="left-column">
          <img src="/image.jpg" alt="Mock Interview" />
          <h1>Mock Interview</h1>
        </div>
        <hr />
        <div className="right-column">
          <div className="login-container">
            <h2>Login</h2>
            <form onSubmit={handleLogin} className="login-form">
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input
                  type="email"
                  id="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Enter your email"
                  required
                />
              </div>
              <div className="form-group">
                <label htmlFor="password">Password</label>
                <input
                  type="password"
                  id="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  required
                />
              </div>
              <div className="form-group radio-buttons">
                <label>User Type</label>
                <div className="radio-options">
                  <div>
                    <input
                      type="radio"
                      value="admin"
                      checked={userType === 'admin'}
                      onChange={(e) => setUserType(e.target.value)}
                    />
                    <label>Admin</label>
                  </div>
                  <div>
                    <input
                      type="radio"
                      value="student"
                      checked={userType === 'student'}
                      onChange={(e) => setUserType(e.target.value)}
                    />
                    <label>Student</label>
                  </div>
                </div>
              </div>
              <button type="submit" disabled={isSubmitting} className="login-button">
                {isSubmitting ? 'Logging in...' : 'Login'}
              </button>
              <br />
              <br />
              <button type="button" onClick={() => navigate('/sign-up')} className="signup-button">
                Sign Up
              </button>
            </form>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default LoginPage;
